    rollupOptions: {
      output: {
        manualChunks(moduleId) {
          if (moduleId.includes("node_modules/react-router")) return "router";
          if (moduleId.includes("node_modules/react")) return "react";
          if (moduleId.includes("node_modules/@datadog")) return "datadog";
          if (
