import type {
  ExtensionContext,
  ToolCallEvent,
  ToolCallEventResult,
} from "@earendil-works/pi-coding-agent";
import type { RuleResult } from "@nizos/probity/rules";
import type { Action } from "@nizos/probity/types";
import { isAbsolute, resolve } from "node:path";

import { toPendingWrite } from "./action-adapter.js";
import { isBehaviorCodePath } from "./path-policy.js";
import { shellMutationReason } from "./shell-guard.js";

export type GuardState = Readonly<{ active: boolean }>;
export type WriteEvaluator = (
  action: Extract<Action, { kind: "write" }>,
  context: ExtensionContext,
) => Promise<RuleResult>;

export async function guardToolCall(
  event: ToolCallEvent,
  context: ExtensionContext,
  state: GuardState,
  cwd: string,
  evaluateWrite: WriteEvaluator,
): Promise<ToolCallEventResult | undefined> {
  if (!state.active) {
    return undefined;
  }

  if (event.toolName === "bash") {
    const command = event.input.command;
    if (typeof command !== "string") {
      return { block: true, reason: "TDD Guard received a malformed bash command." };
    }
    const reason = shellMutationReason(command);
    return reason === undefined ? undefined : { block: true, reason };
  }

  if (event.toolName !== "write" && event.toolName !== "edit") {
    return undefined;
  }

  const filePath = event.input.path;
  if (typeof filePath !== "string" || filePath.length === 0) {
    return { block: true, reason: "TDD Guard received a source write without a path." };
  }
  const absolutePath = isAbsolute(filePath) ? resolve(filePath) : resolve(cwd, filePath);
  if (!isBehaviorCodePath(absolutePath)) {
    return undefined;
  }

  const pending = await toPendingWrite(
    { toolName: event.toolName, input: event.input },
    cwd,
  );
  if (!pending.ok) {
    return { block: true, reason: pending.reason };
  }

  try {
    const result = await evaluateWrite(pending.action, context);
    if (result.kind === "pass") {
      return undefined;
    }
    if (result.kind === "violation" && result.reason.trim().length > 0) {
      return { block: true, reason: result.reason };
    }
    return { block: true, reason: "TDD Guard received an invalid result from Probity." };
  } catch (error: unknown) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      block: true,
      reason: `TDD Guard failed closed because validation could not complete: ${message}`,
    };
  }
}

import type { GuardState } from "./guard-engine.js";

export const GUARD_STATE_ENTRY = "pi-tdd-guard-state";

export function loadGuardState(entries: readonly unknown[]): GuardState {
  for (let index = entries.length - 1; index >= 0; index -= 1) {
    const entry = entries[index];
    if (!isRecord(entry) || entry.type !== "custom") {
      continue;
    }
    if (entry.customType !== GUARD_STATE_ENTRY || !isRecord(entry.data)) {
      continue;
    }
    if (typeof entry.data.active === "boolean") {
      return { active: entry.data.active };
    }
  }

  return { active: true };
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

import type { ExtensionContext } from "@earendil-works/pi-coding-agent";
import { enforceTdd, type RuleResult } from "@nizos/probity/rules";
import type { Agent } from "@nizos/probity/types";
import { readFile, stat } from "node:fs/promises";

import type { WriteEvaluator } from "./guard-engine.js";
import { toRawHistory } from "./history-adapter.js";
import { TDD_RULES } from "./tdd-policy.js";
import { createPiValidatorAgent } from "./validator-agent.js";

const FILE_SIZE_BYTES_MAX = 1_000_000;
const enforceTddRule = enforceTdd({
  instructions: TDD_RULES,
  maxEvents: 16,
  maxContentChars: 8_000,
  fastPath: false,
});

type AgentFactory = (context: ExtensionContext) => Agent;

export function createProbityWriteEvaluator(
  createAgent: AgentFactory = (context) => createPiValidatorAgent(context, context.signal),
): WriteEvaluator {
  return async (action, context): Promise<RuleResult> => {
    if (action.path.length === 0) {
      throw new Error("TDD Guard cannot evaluate a source write without a path.");
    }

    return enforceTddRule(action, {
      agent: createAgent(context),
      rawHistory: async () => toRawHistory(context.sessionManager.getBranch()),
      readFile: readFileForProbity,
    });
  };
}

async function readFileForProbity(filePath: string) {
  if (filePath.length === 0) {
    return { kind: "unknown" as const };
  }

  try {
    const metadata = await stat(filePath);
    if (!metadata.isFile() || metadata.size > FILE_SIZE_BYTES_MAX) {
      return { kind: "unknown" as const };
    }
    const content = await readFile(filePath, { encoding: "utf8" });
    return { kind: "present" as const, content };
  } catch (error: unknown) {
    if (isMissingFileError(error)) {
      return { kind: "absent" as const };
    }
    return { kind: "unknown" as const };
  }
}

function isMissingFileError(error: unknown): boolean {
  if (typeof error !== "object" || error === null) {
    return false;
  }
  return "code" in error && error.code === "ENOENT";
}

