import { defineConfig } from "@playwright/test";

import {
  backendBaseUrl,
  backendEnv,
  backendPython,
  backendRoot,
  backendTmpDir,
  e2eTmpDir,
  frontendBaseUrl,
  frontendRoot,
} from "../helpers/config";

const correctedBackendEnv = {
  ...backendEnv,
  SECRET_KEY: "playwright-secret-key-with-at-least-32-bytes",
};

export default defineConfig({
  testDir: "..",
  fullyParallel: false,
  workers: 1,
  timeout: 30_000,
  expect: {
    timeout: 5_000,
  },
  use: {
    baseURL: frontendBaseUrl,
    trace: "on-first-retry",
  },
  webServer: [
    {
      command: "node ./e2e/mock-sidecar.mjs",
      cwd: frontendRoot,
      url: "http://127.0.0.1:9777",
      reuseExistingServer: false,
      env: {
        ...correctedBackendEnv,
        MOCK_SIDECAR_HEALTH_PORT: "9777",
      },
    },
    {
      command: `bash -lc 'mkdir -p "${backendTmpDir}" "$USER_DATA_DIR" && "${backendPython}" -m uvicorn yinshi.main:app --host 127.0.0.1 --port 8000'`,
      cwd: backendRoot,
      url: `${backendBaseUrl}/health`,
      reuseExistingServer: false,
      env: correctedBackendEnv,
    },
    {
      command: `bash -lc 'mkdir -p "${e2eTmpDir}" && npm run dev -- --host 127.0.0.1 --port 5173'`,
      cwd: frontendRoot,
      url: frontendBaseUrl,
      reuseExistingServer: false,
    },
  ],
});

